async def process_new_local_api_orders_hourly():
    """Process one page of new orders and post the exact integer batch summary.

    Evolved cents/minor-unit and endpoint-semantic per-unit price aliases are
    accepted without changing the aggregation or exact POST contract.
    """
    import json
    import logging
    import re
    from collections import defaultdict
    from urllib.parse import urlencode
    from urllib.request import Request, urlopen

    logger = logging.getLogger(__name__)
    base_url = "http://127.0.0.1:8125"

    def get_json(url):
        request = Request(url, method="GET", headers={"Accept": "application/json"})
        with urlopen(request, timeout=30) as response:
            return json.loads(response.read().decode("utf-8"))

    def require_int(value, field):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"{field} must be an integer")
        return value

    def words(value):
        expanded = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", str(value))
        return tuple(part for part in re.split(r"[^a-z0-9]+", expanded.lower()) if part)

    def path_words(path):
        return tuple(part for component in path for part in words(component))

    def walk_scalars(value, path=()):
        if isinstance(value, dict):
            for key, child in value.items():
                yield from walk_scalars(child, path + (str(key),))
        elif isinstance(value, list):
            for position, child in enumerate(value):
                yield from walk_scalars(child, path + (str(position),))
        else:
            yield path, value

    def walk_objects(value, path=()):
        if isinstance(value, dict):
            yield path, value
            for key, child in value.items():
                yield from walk_objects(child, path + (str(key),))
        elif isinstance(value, list):
            for position, child in enumerate(value):
                yield from walk_objects(child, path + (str(position),))

    def semantic_flags(tokens):
        token_set = set(tokens)
        joined = "".join(tokens)
        price = bool(token_set & {"price", "pricing", "cost", "rate", "amount"})
        if any(term in joined for term in ("price", "pricing", "cost", "rate", "amount")):
            price = True
        per_item = bool(token_set & {"unit", "item", "each"})
        if any(term in joined for term in (
            "perunit", "peritem", "unitprice", "itemprice", "priceperunit",
            "priceperitem", "unitcost", "itemcost", "costperunit",
            "costperitem", "unitrate", "itemrate", "rateperunit", "rateperitem",
        )):
            per_item = True
        aggregate = bool(token_set & {
            "total", "subtotal", "extended", "extension", "revenue", "gross", "net"
        })
        cents = bool(token_set & {"cent", "cents", "minor"})
        if "cent" in joined or "minorunit" in joined or "minoramount" in joined:
            cents = True
        other_scale = bool(token_set & {
            "dollar", "dollars", "major", "micro", "micros", "milli", "mills"
        })
        if any(term in joined for term in ("majorunit", "microunit", "millis")):
            other_scale = True
        return price, per_item, aggregate, cents, other_scale

    def scalar_is_unit_price(path):
        if not path:
            return False
        leaf_joined = "".join(words(path[-1]))
        if leaf_joined in {
            "currency", "currencycode", "code", "denomination", "currencyunit",
            "amountunit", "unitofmeasure", "basis", "per", "quantitybasis",
            "type", "kind", "role", "name", "scale", "representation",
        }:
            return False
        price, per_item, aggregate, cents, other_scale = semantic_flags(path_words(path))
        if aggregate or other_scale or not price:
            return False
        if cents and per_item:
            return True
        if per_item and leaf_joined in {
            "unitprice", "itemprice", "priceperunit", "priceperitem", "unitcost",
            "itemcost", "costperunit", "costperitem", "unitrate", "itemrate",
            "rateperunit", "rateperitem", "amount", "value", "minoramount",
        }:
            return True
        if cents:
            harmless = {
                "order", "orders", "data", "attributes", "details", "pricing",
                "price", "cost", "rate", "amount", "value", "cent", "cents",
                "minor", "unit", "units",
            }
            if not (set(path_words(path)) - harmless):
                return True
        return False

    def normalized_object(node):
        return {"".join(words(key)): (str(key), value) for key, value in node.items()}

    def object_unit_price(path, node):
        normalized = normalized_object(node)
        descriptor_tokens = []
        for key in ("type", "kind", "role", "name", "basis", "per", "quantitybasis"):
            if key in normalized and isinstance(normalized[key][1], str):
                descriptor_tokens.extend(words(normalized[key][1]))
        price, per_item, aggregate, cents, other_scale = semantic_flags(
            path_words(path) + tuple(descriptor_tokens)
        )

        denomination = None
        for key in (
            "denomination", "currencyunit", "amountunit", "unitofmeasure",
            "representation", "scale",
        ):
            if key in normalized:
                denomination = normalized[key][1]
                break
        denomination_name = "".join(words(denomination)) if isinstance(denomination, str) else ""
        explicit_cents = denomination_name in {
            "cent", "cents", "minor", "minorunit", "minorunits"
        }
        explicit_other = denomination_name in {
            "dollar", "dollars", "major", "majorunit", "majorunits",
            "micro", "micros", "milli", "mills",
        }
        for key in ("inminorunits", "isminorunits"):
            if key in normalized and normalized[key][1] is True:
                explicit_cents = True

        if aggregate or other_scale or explicit_other or not price:
            return None
        if not per_item and not (cents or explicit_cents):
            return None
        for key in (
            "amount", "value", "minoramount", "minorunits", "minor", "cents", "cent"
        ):
            if key in normalized:
                original_key, value = normalized[key]
                return original_key, value
        return None

    def read_unit_price_cents(order, index):
        candidates = {}
        for path, value in walk_scalars(order):
            if value is not None and scalar_is_unit_price(path):
                candidates[path] = value
        for path, node in walk_objects(order):
            candidate = object_unit_price(path, node)
            if candidate is not None:
                value_key, value = candidate
                candidate_path = path + (value_key,)
                if value is not None and candidate_path not in candidates:
                    candidates[candidate_path] = value

        if not candidates:
            raise TypeError(
                f"order[{index}].unit_price_cents was not found in an equivalent per-unit integer price, cost, or rate field"
            )
        validated = []
        for path, value in candidates.items():
            field = f"order[{index}]." + ".".join(path)
            validated.append((field, require_int(value, field)))
        distinct_values = {value for _, value in validated}
        if len(distinct_values) != 1:
            fields = ", ".join(field for field, _ in validated)
            raise ValueError(f"order[{index}] contains conflicting equivalent unit-price fields: {fields}")
        source, result = validated[0]
        if source != f"order[{index}].unit_price_cents":
            logger.info("PHASE adapt_unit_price_field order_index=%s source=%s", index, source)
        return result

    logger.info("PHASE fetch_last_seq")
    last_payload = get_json(f"{base_url}/batches/last")
    if not isinstance(last_payload, dict) or "last_seq" not in last_payload:
        raise ValueError("GET /batches/last did not return an object containing last_seq")
    last_seq = require_int(last_payload["last_seq"], "last_seq")

    logger.info("PHASE fetch_single_order_page after=%s", last_seq)
    orders_payload = get_json(f"{base_url}/orders?{urlencode({'after': last_seq})}")
    if isinstance(orders_payload, list):
        orders = orders_payload
    elif isinstance(orders_payload, dict) and isinstance(orders_payload.get("orders"), list):
        orders = orders_payload["orders"]
    else:
        raise ValueError("GET /orders response did not contain an order list")

    if len(orders) > 200:
        raise ValueError(
            f"GET /orders returned {len(orders)} orders; refusing to process more than 200 in one run"
        )
    if not orders:
        logger.info("SKIP no_new_orders after=%s; no POST performed", last_seq)
        return {"status": "success", "last_seq": last_seq, "orders_returned": 0, "posted": False}

    seqs = []
    total_units = 0
    total_revenue_cents = 0
    revenue_by_region = defaultdict(int)
    logger.info("PHASE aggregate_order_page count=%s", len(orders))
    for index, order in enumerate(orders):
        if not isinstance(order, dict):
            raise TypeError(f"order[{index}] must be an object")
        seq = require_int(order.get("seq"), f"order[{index}].seq")
        units = require_int(order.get("units"), f"order[{index}].units")
        unit_price_cents = read_unit_price_cents(order, index)
        region = order.get("region")
        if not isinstance(region, str):
            raise TypeError(f"order[{index}].region must be a string")
        if seq <= last_seq:
            raise ValueError(f"order[{index}].seq must be greater than last_seq")

        revenue_cents = units * unit_price_cents
        seqs.append(seq)
        total_units += units
        total_revenue_cents += revenue_cents
        revenue_by_region[region] += revenue_cents

    batch = {
        "batch_start_seq": min(seqs),
        "batch_end_seq": max(seqs),
        "order_count": len(orders),
        "total_units": total_units,
        "total_revenue_cents": total_revenue_cents,
        "revenue_by_region_cents": dict(revenue_by_region),
    }
    required_keys = {
        "batch_start_seq", "batch_end_seq", "order_count", "total_units",
        "total_revenue_cents", "revenue_by_region_cents",
    }
    if set(batch) != required_keys:
        raise AssertionError("batch payload keys do not exactly match the required contract")

    logger.info(
        "PHASE post_batch start_seq=%s end_seq=%s count=%s",
        batch["batch_start_seq"], batch["batch_end_seq"], batch["order_count"],
    )
    body = json.dumps(batch, separators=(",", ":")).encode("utf-8")
    request = Request(
        f"{base_url}/batches",
        data=body,
        method="POST",
        headers={"Content-Type": "application/json", "Accept": "application/json"},
    )
    with urlopen(request, timeout=30) as response:
        response.read()
        status_code = response.status

    logger.info("PHASE complete posted_batch status_code=%s", status_code)
    return {"status": "success", "posted": True, "http_status": status_code, "batch": batch}
